INSERT INTO `analysis_result` (`id`, `task_id`, `baseline_json`, `target_json`, `delta_json`, `suggestion_json`, `confidence`, `data_completeness`, `summary`, `explanation`, `engine_version`, `created_at`) VALUES (5,5,'{\"scores\": {\"sour\": 21.56, \"salty\": 0.47, \"spicy\": 0, \"sweet\": 77.35, \"umami\": 0.04, \"bitter\": 1.23, \"numbing\": 0, \"fat_aroma\": 0}, \"itemCount\": 4, \"totalAmount\": 105.5}','{\"scores\": {\"sour\": 28.16, \"salty\": 0.62, \"spicy\": 0, \"sweet\": 46.58, \"umami\": 0.05, \"bitter\": 3.72, \"numbing\": 0, \"fat_aroma\": 0}, \"itemCount\": 5, \"totalAmount\": 80.8}','[{\"diff\": -30.77, \"note\": \"命中规则「减糖场景甜味平衡」：减糖后甜味下降明显时提示代糖复配与后味风险，仍需感官试验验证。\", \"status\": \"DOWN\", \"target\": 46.58, \"baseline\": 77.35, \"dimension\": \"sweet\", \"direction\": \"下降\", \"statusText\": \"下降\", \"changePercent\": -39.78, \"dimensionLabel\": \"甜\"}, {\"diff\": 0.15, \"note\": null, \"status\": \"UP\", \"target\": 0.62, \"baseline\": 0.47, \"dimension\": \"salty\", \"direction\": \"上升\", \"statusText\": \"上升\", \"changePercent\": 15, \"dimensionLabel\": \"咸\"}, {\"diff\": 6.6, \"note\": null, \"status\": \"UP\", \"target\": 28.16, \"baseline\": 21.56, \"dimension\": \"sour\", \"direction\": \"上升\", \"statusText\": \"上升\", \"changePercent\": 30.61, \"dimensionLabel\": \"酸\"}, {\"diff\": 2.49, \"note\": \"主要来自：「赤藓糖醇」贡献增加 165.00\", \"status\": \"UP\", \"target\": 3.72, \"baseline\": 1.23, \"dimension\": \"bitter\", \"direction\": \"上升\", \"statusText\": \"上升\", \"changePercent\": 202.44, \"dimensionLabel\": \"苦\"}, {\"diff\": 0.01, \"note\": null, \"status\": \"STABLE\", \"target\": 0.05, \"baseline\": 0.04, \"dimension\": \"umami\", \"direction\": \"稳定\", \"statusText\": \"稳定\", \"changePercent\": 1, \"dimensionLabel\": \"鲜\"}, {\"diff\": 0, \"note\": null, \"status\": \"STABLE\", \"target\": 0, \"baseline\": 0, \"dimension\": \"spicy\", \"direction\": \"稳定\", \"statusText\": \"稳定\", \"changePercent\": 0, \"dimensionLabel\": \"辣\"}, {\"diff\": 0, \"note\": null, \"status\": \"STABLE\", \"target\": 0, \"baseline\": 0, \"dimension\": \"numbing\", \"direction\": \"稳定\", \"statusText\": \"稳定\", \"changePercent\": 0, \"dimensionLabel\": \"麻\"}, {\"diff\": 0, \"note\": null, \"status\": \"STABLE\", \"target\": 0, \"baseline\": 0, \"dimension\": \"fat_aroma\", \"direction\": \"稳定\", \"statusText\": \"稳定\", \"changePercent\": 0, \"dimensionLabel\": \"脂香\"}]','[{\"risk\": \"代糖复配存在后味风险，需做后味与感官复核。\", \"reason\": \"减糖后甜味下降明显时提示代糖复配与后味风险，仍需感官试验验证。\", \"target\": \"代糖复配、酸甜平衡调整\", \"ruleCode\": \"SWEET_DROP_REDUCE_SUGAR\", \"ruleName\": \"减糖场景甜味平衡\", \"dimension\": \"sweet\", \"direction\": \"提示关注：甜（当前下降 -39.78%）\", \"actionText\": \"提示关注\", \"actionType\": \"NOTICE\", \"candidates\": [\"代糖复配\", \"酸甜平衡调整\"], \"changeText\": \"-39.78%\", \"dimensionLabel\": \"甜\", \"referenceRange\": \"无固定幅度，按打样结果微调\"}]',86.67,100.00,'本次分析对比「0 糖茶饮基底」与目标方案，共 5 项配料；主要变化：苦 上升 202.44%、甜 下降 39.78%、酸 上升 30.61% 等 4 个维度。命中 1 条规则，给出 1 条参考建议。','一、计算口径\n基准与目标的风味向量均按「食材用量占比 × 该食材的维度属性值」加权平均得到（0-100 相对评分），已按各自配方总量归一化，因此总用量不同的配方之间可以比较。\n偏移比例 =（目标得分 - 基准得分）/ max(|基准得分|, 1) × 100%；变化幅度小于 ±5% 视为稳定。\n区域折算：本次未选择目标区域，按全国基准口径计算。\n\n二、结果与依据\n主要影响因素：甜：「白砂糖」贡献减少 8000.00，「赤藓糖醇」贡献增加 3575.00；苦：「赤藓糖醇」贡献增加 165.00。\n命中规则：减糖场景甜味平衡，对应建议已在建议表中给出触发原因与参考幅度。\n\n三、数据完整度与置信度\n基准配方数据完整度 100%，目标配方数据完整度 100%；结果置信度 = 完整度 × 0.8 + 规则覆盖率 × 0.2 = 86.67%。\n\n四、免责声明\n本结果基于课程设计阶段的演示数据与结构化规则生成，不等同于实验室仪器检测或感官评价结论，也不构成新品上市成功率的预测。最终配方仍需经过试产、感官评价与食品安全审核。','RULE-1.0','2026-09-16 09:01:43');
