INSERT INTO `flavor_rule` (`id`, `rule_code`, `rule_name`, `goal_type`, `priority`, `condition_json`, `action_json`, `explanation`, `status`, `created_at`, `updated_at`) VALUES (1,'UMAMI_DROP_GENERAL','鲜味明显下降补偿','GENERAL',10,'{\"operator\": \"LTE\", \"dimension\": \"umami\", \"changePercent\": -10}','{\"actionType\": \"ADD\", \"candidates\": [\"酵母抽提物\", \"香菇粉\"], \"referencePercentMax\": 0.30, \"referencePercentMin\": 0.05}','当鲜味相对下降达到10%时，从启用的高鲜味原料中给出候选补偿方向。',1,'2026-09-15 22:04:47','2026-09-15 22:04:47');
INSERT INTO `flavor_rule` (`id`, `rule_code`, `rule_name`, `goal_type`, `priority`, `condition_json`, `action_json`, `explanation`, `status`, `created_at`, `updated_at`) VALUES (2,'FAT_AROMA_DROP_REDUCE_FAT','控脂场景脂香下降提醒','REDUCE_FAT',20,'{\"operator\": \"LTE\", \"dimension\": \"fat_aroma\", \"changePercent\": -15}','{\"actionType\": \"NOTICE\", \"candidates\": [\"低用量增香方案\", \"工艺增香方案\"], \"restoreFatDirectly\": false}','控脂目标下脂香下降时，不直接建议恢复原油脂用量，应优先给出低用量或工艺补偿方向。',1,'2026-09-15 22:04:47','2026-09-15 22:04:47');
INSERT INTO `flavor_rule` (`id`, `rule_code`, `rule_name`, `goal_type`, `priority`, `condition_json`, `action_json`, `explanation`, `status`, `created_at`, `updated_at`) VALUES (3,'SPICY_OVER_TARGET','辣度超过目标范围','ADJUST_STIMULATION',30,'{\"operator\": \"GTE\", \"dimension\": \"spicy\", \"changePercent\": 15}','{\"actionType\": \"REDUCE\", \"ingredientCategory\": \"香辛料\", \"referencePercentMax\": 20, \"referencePercentMin\": 5}','当辣度明显上升时，提示降低主要辣味原料并重新分析。',1,'2026-09-15 22:04:47','2026-09-15 22:04:47');
INSERT INTO `flavor_rule` (`id`, `rule_code`, `rule_name`, `goal_type`, `priority`, `condition_json`, `action_json`, `explanation`, `status`, `created_at`, `updated_at`) VALUES (4,'SWEET_DROP_REDUCE_SUGAR','减糖场景甜味平衡','REDUCE_SUGAR',40,'{\"operator\": \"LTE\", \"dimension\": \"sweet\", \"changePercent\": -20}','{\"actionType\": \"NOTICE\", \"candidates\": [\"代糖复配\", \"酸甜平衡调整\"], \"requireAftertasteCheck\": true}','减糖后甜味下降明显时提示代糖复配与后味风险，仍需感官试验验证。',1,'2026-09-15 22:04:47','2026-09-15 22:04:47');
