INSERT INTO `knowledge_article` (`id`, `category_id`, `author_id`, `title`, `summary`, `content`, `cover_url`, `source_name`, `source_url`, `content_hash`, `status`, `view_count`, `published_at`, `created_at`, `updated_at`) VALUES (1,1,3,'八维风味向量：把“好吃”拆成可计算的数字','甜、咸、酸、苦、鲜、辣、麻、脂香八个维度如何取值、如何加权，以及为什么必须做归一化。','<h2>为什么是八个维度</h2>\n<p>舌头能直接说出的味道只有甜、咸、酸、苦、鲜五种，而决定“这碗汤厚不厚”“这口辣上不上头”的，往往是说不清的那几维：辣、麻、脂香。</p>\n<h2>取值口径</h2>\n<ul>\n  <li>每个食材在每个维度上取 0-100 的相对评分，表示“该食材在这个维度上的强度”；</li>\n  <li>配方维度得分 = Σ（食材用量占比 × 该食材的维度属性值），是一致化后的加权平均；</li>\n  <li>必须按配方总用量归一化，否则“配方做大一倍”会让所有维度凭空翻倍。</li>\n</ul>\n<blockquote>演示数据说明：本平台的属性值用于验证业务与技术闭环，不等同于实验室检测结果。</blockquote>',NULL,'食之有理研发手册','https://example.com/flavor/8d-vector','4a605949f87176fd2b4dd504957329bd056c597178a8a92aaf12d902cc2e055d',1,1,'2026-09-16 09:01:41','2026-09-16 09:01:41','2026-09-16 09:01:51');
INSERT INTO `knowledge_article` (`id`, `category_id`, `author_id`, `title`, `summary`, `content`, `cover_url`, `source_name`, `source_url`, `content_hash`, `status`, `view_count`, `published_at`, `created_at`, `updated_at`) VALUES (2,2,3,'酵母抽提物与味精：两条鲜味路径的差异','同样补鲜，为什么控脂配方更倾向酵母抽提物？从鲜味强度、后味与标签友好度三个角度看。','<h2>两条路径</h2>\n<p>味精提供的是直接、干净的鲜味；酵母抽提物除鲜味外还带有核苷酸与氨基酸带来的醇厚感，在减油减盐的配方里更容易补上“厚度”。</p>\n<h2>替换时的注意点</h2>\n<ul>\n  <li>酵母抽提物用量通常在 0.05%-0.30%（占配方总量），过量会带来发酵气味；</li>\n  <li>与香菇粉复配可以拉长鲜味尾巴；</li>\n  <li>补鲜无法替代脂香，控脂场景应同时考虑低用量增香或工艺增香。</li>\n</ul>',NULL,'食之有理研发手册','https://example.com/ingredient/umami-paths','2bb2e4d9361923493cd5003f1dc017066f9060f92b064f0f855f0ac07ce08d4f',1,0,'2026-09-16 09:01:41','2026-09-16 09:01:41','2026-09-16 09:01:41');
INSERT INTO `knowledge_article` (`id`, `category_id`, `author_id`, `title`, `summary`, `content`, `cover_url`, `source_name`, `source_url`, `content_hash`, `status`, `view_count`, `published_at`, `created_at`, `updated_at`) VALUES (3,3,3,'减糖 30% 之后，甜味为什么“塌”了','甜味下降不只是数值变小，酸甜平衡与后味风险才是研发真正要处理的问题。','<h2>三个连锁反应</h2>\n<ol>\n  <li>甜度下降后酸味相对突出，整体轮廓向“尖”偏移；</li>\n  <li>代糖存在后味：赤藓糖醇的凉感、甜菊糖苷的金属与后苦、三氯蔗糖的苦尾；</li>\n  <li>减糖会同时削弱体感厚度，需要靠增稠或微量盐来补。</li>\n</ol>\n<h2>可执行的思路</h2>\n<p>复配代糖、微调酸度、少量食盐增甜，再用分析结果验证“甜度回到目标区间、苦味没有明显上升”。</p>',NULL,'食之有理研发手册','https://example.com/health/sugar-reduction','107f72b8459b25af61c862fc897d34d6b1f8c38f78c52b03b7c624baa5f39a6e',1,0,'2026-09-16 09:01:41','2026-09-16 09:01:41','2026-09-16 09:01:41');
INSERT INTO `knowledge_article` (`id`, `category_id`, `author_id`, `title`, `summary`, `content`, `cover_url`, `source_name`, `source_url`, `content_hash`, `status`, `view_count`, `published_at`, `created_at`, `updated_at`) VALUES (4,3,3,'控脂改造：脂香下降不等于只能把油加回去','油脂减少会同时带走脂香与载香能力，补偿方向应优先低用量增香与工艺增香。','<h2>脂香为什么掉得最快</h2>\n<p>油脂不只提供口感，还承担香气溶剂的作用。用量下降后，脂溶性香气物质的释放也随之减弱，因此脂香维度往往最先报警。</p>\n<h2>不建议的做法</h2>\n<p>控脂目标下直接把原油脂用量加回去，等于放弃研发目标。</p>\n<h2>建议方向</h2>\n<ul>\n  <li>低用量增香：鸡油、香辛料精油等少量高效原料；</li>\n  <li>工艺增香：先炒后煮、分段投料，提高香气物质的保留率；</li>\n  <li>结构补偿：用胶体或淀粉体系补回厚度感。</li>\n</ul>',NULL,'食之有理研发手册','https://example.com/health/fat-reduction','34fef1dcb2abdf64b24ec18bfc4dc89354f38a42e7e765a382e0491103838ff3',1,0,'2026-09-16 09:01:41','2026-09-16 09:01:41','2026-09-16 09:01:41');
INSERT INTO `knowledge_article` (`id`, `category_id`, `author_id`, `title`, `summary`, `content`, `cover_url`, `source_name`, `source_url`, `content_hash`, `status`, `view_count`, `published_at`, `created_at`, `updated_at`) VALUES (5,4,3,'一版打全国为什么难：西南、华东、华南的口味差异','同一份基准配方，在不同区域需要调整的维度并不相同，用权重描述偏好比“多放点辣”更可执行。','<h2>用权重描述偏好</h2>\n<p>平台为每个区域维护八个维度的偏好权重：1.000 表示与全国基准一致，大于 1 表示偏好更强。</p>\n<table>\n  <thead><tr><th>区域</th><th>更偏好</th><th>相对收敛</th></tr></thead>\n  <tbody>\n    <tr><td>西南地区</td><td>辣 1.20、麻 1.25</td><td>苦 0.95</td></tr>\n    <tr><td>华东地区</td><td>甜 1.15</td><td>辣 0.80、麻 0.80</td></tr>\n    <tr><td>华南地区</td><td>鲜 1.15</td><td>辣 0.75、脂香 0.85</td></tr>\n  </tbody>\n</table>\n<p>区域适配的正确用法是“一个基准配方 + 三套微调参数”，而不是重做三份配方。</p>',NULL,'食之有理研发手册','https://example.com/region/taste-profile','4e6840b6a25020f5d21149dc24ab5148f301589dec000f93b513caa816197d1f',1,0,'2026-09-16 09:01:42','2026-09-16 09:01:42','2026-09-16 09:01:42');
INSERT INTO `knowledge_article` (`id`, `category_id`, `author_id`, `title`, `summary`, `content`, `cover_url`, `source_name`, `source_url`, `content_hash`, `status`, `view_count`, `published_at`, `created_at`, `updated_at`) VALUES (6,5,3,'研发案例：牛肉换鸡胸肉，一次可解释的配方推演','主料替换造成脂香与鲜味同时下降时，系统如何给出候选补偿方向与参考幅度。','<h2>背景</h2>\n<p>牛肉成本上涨，研发希望用鸡胸肉替代主料并保持“肉香与鲜味”。</p>\n<h2>推演结果</h2>\n<p>替换后脂香与鲜味明显下降，系统命中“鲜味明显下降补偿”规则，给出酵母抽提物、香菇粉等候选方向与 0.05%-0.30% 的参考幅度，并提示“补鲜不能替代脂香”。</p>\n<h2>落地</h2>\n<p>按建议调整第 2 版配方后重新分析，确认鲜味回到基准区间、脂香不再报警，再进入试产与感官评价。</p>',NULL,'食之有理研发手册','https://example.com/case/beef-to-chicken','8cd85ad9a7c89c273bbf4529e79f4bf8dc48602074b82d317d99cf7ddc49eb6b',1,0,'2026-09-16 09:01:42','2026-09-16 09:01:42','2026-09-16 09:01:42');
/*!40000 ALTER TABLE `knowledge_article` ENABLE KEYS */;
UNLOCK TABLES;

